package com.oms.order.service;

import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.time.LocalDateTime;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.*;

/** Durable HH controls. Warehouse cancellation, inventory adjustment and business closure are separate facts. */
@Service public class ExchangeControlService {
    @Resource private OrderRepository repository;
    @Resource private ExchangeService exchanges;
    @Resource private ExchangeReturnClient returns;
    @Resource private OrderShipmentWmsClient wms;
    @Resource private OrderWarehouseClient inventory;
    @Resource private ExchangeFulfillment fulfillment;
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    static boolean terminal(Map<String,Object> e){return Arrays.asList("CANCELED","CLOSED","REJECTED","COMPLETED").contains(text(e,"state"));}
    private void idle(Map<String,Object> e){require(e.get("lease_until")==null||!time(text(e,"lease_until")).isAfter(LocalDateTime.now()),"换货任务正在执行，请稍后刷新");}
    public Map<String,Object> report(String company,long id){Map<String,Object> e=exchanges.row(company,id,false);return map("hold",number(e,"fulfillment_hold"),"state",e.get("control_state"),"operations",repository.db().query("SELECT id,parent_id,kind,document_id,mode,state,reason,actor,last_error,create_time,update_time FROM oms_exchange_control WHERE company_code=? AND exchange_id=? ORDER BY id DESC LIMIT 100",ROW,company,id));}
    private Map<String,Object> editable(String company,long id,Map<String,Object> input){Map<String,Object> e=exchanges.row(company,id,true);require(!ExchangeFulfillment.unshipped(e)&&e.get("linked_exchange_id")==null,"请在退回换出的实际处理单操作；未发货换品从原订单处理");require(number(input,"control_version")==number(e,"control_version"),"换货单已变化，请刷新");require(!terminal(e),"换货单已结束");require(!"CONTINUE_REVIEW".equals(text(e,"control_state")),"继续换出申请待审核，请先审核或拒绝该申请");idle(e);require(Arrays.asList("NONE","FAILED").contains(text(e,"platform_operation")),"平台操作尚未核对，请先确认原操作结果");return e;}
    public Map<String,Object> request(String company,long id,Map<String,Object> input,String actor){
        String kind=text(input,"kind"),mode=text(input,"mode"),reason=text(input,"reason").trim();long document=number(input,"document_id");
        require(Arrays.asList("RETURN","OUTBOUND","CANCEL").contains(kind)&&Arrays.asList("WITHDRAW","TERMINATE").contains(mode)&&!reason.isEmpty()&&reason.length()<=200,"请选择截单范围、目的，并填写1至200字原因");require(!"CANCEL".equals(kind)||"TERMINATE".equals(mode),"取消换货应终止剩余履约");
        Map<String,Object> before=exchanges.row(company,id,false);Map<String,Object> returnReport=text(before,"return_sn").isEmpty()?Collections.emptyMap():data(returns.detail(company,id,SecurityConstants.INNER));
        tx().execute(s->{Map<String,Object> e=editable(company,id,input);require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_control WHERE company_code=? AND exchange_id=? AND state<>'COMPLETED'",Long.class,company,id)==0,"已有截单待处理，请核对原申请");require(!"CANCELING".equals(text(e,"control_state"))&&!"CANCEL_REVIEW".equals(text(e,"control_state")),"正在取消换货，请核对原申请");
            long op=insert(company,id,kind,document,mode,reason,actor,number(e,"control_version"),null);
            List<Map<String,Object>> docs=maps(returnReport.get("documents"));
            if("RETURN".equals(kind))require(docs.stream().anyMatch(d->number(d,"id")==document&&number(d,"accepted_quantity")<number(d,"quantity")&&!"CONFIRMED".equals(text(d,"cancel_state"))),"退回单不属于本次申请或没有可截停余量");
            List<Map<String,Object>> ships=repository.db().query("SELECT s.*,COALESCE((SELECT SUM(l.shipped_quantity) FROM oms_order_shipment_line l WHERE l.company_code=s.company_code AND l.shipment_id=s.id),0) shipped_quantity FROM oms_order_shipment s WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE' ORDER BY s.id FOR UPDATE",ROW,company,id);
            if("OUTBOUND".equals(kind))require(ships.stream().anyMatch(d->number(d,"id")==document&&number(d,"quantity")>number(d,"shipped_quantity")+number(d,"cancelled_quantity")),"换出单不属于本次申请或没有可截停余量");
            if("CANCEL".equals(kind)){for(Map<String,Object> d:docs)if(number(d,"accepted_quantity")<number(d,"quantity")&&!"CONFIRMED".equals(text(d,"cancel_state")))insert(company,id,"RETURN",number(d,"id"),mode,reason,actor,number(e,"control_version"),op);for(Map<String,Object> sh:ships)if(number(sh,"quantity")>number(sh,"shipped_quantity")+number(sh,"cancelled_quantity"))insert(company,id,"OUTBOUND",number(sh,"id"),mode,reason,actor,number(e,"control_version"),op);}
            repository.db().update("UPDATE oms_exchange SET fulfillment_hold=1,control_state=?,control_version=control_version+1,next_attempt=NOW() WHERE company_code=? AND id=?","CANCEL".equals(kind)?"CANCELING":"HOLD",company,id);
            exchanges.event(company,id,"CUTOFF_REQUEST",text(e,"state"),number(e,"control_version")+1,"已暂停新增履约并登记"+("CANCEL".equals(kind)?"取消换货，分别截停退回与换出":"RETURN".equals(kind)?"退回截单":"换出截单")+"："+reason,map("operation_id",op,"kind",kind,"document_id",document,"mode",mode),actor);return null;
        });process(company,id);return exchanges.detail(company,id);
    }
    @SuppressWarnings("unchecked") private List<Map<String,Object>> maps(Object raw){return raw instanceof List?(List<Map<String,Object>>)raw:Collections.emptyList();}
    private long insert(String company,long id,String kind,long document,String mode,String reason,String actor,long version,Long parent){return repository.insert("INSERT INTO oms_exchange_control(company_code,exchange_id,kind,document_id,mode,reason,actor,request_version,parent_id) VALUES (?,?,?,?,?,?,?,?,?)",company,id,kind,document,mode,reason,actor,version,parent);}
    public Map<String,Object> hold(String company,long id,Map<String,Object> input,String actor){tx().execute(s->{Map<String,Object> e=editable(company,id,input);require(!text(e,"control_state").startsWith("CANCEL"),"取消流程未结束，不能改为普通挂起");String reason=text(input,"reason").trim();require(!reason.isEmpty()&&reason.length()<=200,"请填写挂起原因");repository.db().update("UPDATE oms_exchange SET fulfillment_hold=1,control_state='HOLD',control_version=control_version+1,next_attempt=NULL WHERE company_code=? AND id=?",company,id);exchanges.event(company,id,"HOLD",text(e,"state"),number(e,"control_version")+1,"已挂起新增履约，不自动通知仓库截单："+reason,Collections.emptyMap(),actor);return null;});return exchanges.detail(company,id);}
    public Map<String,Object> resume(String company,long id,Map<String,Object> input,String actor){
        Map<String,Object> prior=exchanges.row(company,id,false);Map<String,Object> report=text(prior,"return_sn").isEmpty()?Collections.emptyMap():data(returns.detail(company,id,SecurityConstants.INNER));
        tx().execute(s->{Map<String,Object> e=editable(company,id,input);require("HOLD".equals(text(e,"control_state")),"当前不是可恢复的普通挂起");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_control WHERE company_code=? AND exchange_id=? AND state<>'COMPLETED'",Long.class,company,id)==0,"截单尚未确认，请先核对");require(number(report,"pending_review_count")==0,"存在待人工核对的退回回传");
            long active=maps(report.get("documents")).stream().filter(d->!"CONFIRMED".equals(text(d,"cancel_state"))).count();require(report.isEmpty()||number(report,"accepted_quantity")==number(e,"requested_quantity")||active>0,"剩余退回已停止，请先重新安排退回单");
            require(repository.db().queryForObject("SELECT COALESCE(SUM(cancelled_quantity),0) FROM oms_order_line WHERE company_code=? AND exchange_id=? AND business_type='EXCHANGE' AND stock_reference=?",Long.class,company,id,ExchangeRounds.reference(e))==0,"换出需求已终止，请核对后结束本次换货，不能直接恢复原数量");
            repository.db().update("UPDATE oms_exchange SET fulfillment_hold=0,control_state='NONE',control_version=control_version+1,next_attempt=NOW() WHERE company_code=? AND id=?",company,id);exchanges.event(company,id,"RESUME",text(e,"state"),number(e,"control_version")+1,"已恢复新增履约；已撤回单据保留，剩余换出需重新分仓",Collections.emptyMap(),actor);return null;});return exchanges.detail(company,id);
    }
    public Map<String,Object> recheck(String company,long id,Map<String,Object> input,String actor){tx().execute(s->{Map<String,Object> e=editable(company,id,input);repository.db().update("UPDATE oms_exchange_control SET state='PENDING' WHERE company_code=? AND exchange_id=? AND state='REVIEW'",company,id);repository.db().update("UPDATE oms_exchange SET next_attempt=NOW(),control_version=control_version+1 WHERE company_code=? AND id=?",company,id);exchanges.event(company,id,"CUTOFF_QUERY",text(e,"state"),number(e,"control_version")+1,"已请求核对原截单，不重建单据或重复释放库存",Collections.emptyMap(),actor);return null;});process(company,id);return exchanges.detail(company,id);}
    public void process(String company,long id){String lease=token();if(repository.db().update("UPDATE oms_exchange SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=? AND fulfillment_hold=1 AND (lease_until IS NULL OR lease_until<NOW())",lease,company,id)!=1)return;
        try{List<Map<String,Object>> ops=repository.db().query("SELECT * FROM oms_exchange_control WHERE company_code=? AND exchange_id=? AND state='PENDING' AND kind<>'CANCEL' ORDER BY id LIMIT 100",ROW,company,id);for(Map<String,Object> op:ops){require(repository.db().update("UPDATE oms_exchange SET lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=? AND lease_token=? AND lease_until>NOW()",company,id,lease)==1,"截单处理租约已失效");try{if("RETURN".equals(text(op,"kind")))stopReturn(company,id,op);else stopOutbound(company,id,op);complete(company,op);}catch(RuntimeException failure){blocked(company,op,failure);}}
            for(Map<String,Object> op:repository.db().query("SELECT * FROM oms_exchange_control WHERE company_code=? AND exchange_id=? AND kind='CANCEL' AND state='PENDING' ORDER BY id",ROW,company,id)){try{finishCancel(company,id,op);}catch(RuntimeException failure){blocked(company,op,failure);}}
        }finally{repository.db().update("UPDATE oms_exchange SET lease_token=NULL,lease_until=NULL,next_attempt=IF(EXISTS(SELECT 1 FROM oms_exchange_control c WHERE c.company_code=? AND c.exchange_id=? AND c.state='PENDING'),DATE_ADD(NOW(),INTERVAL 60 SECOND),NULL) WHERE company_code=? AND id=? AND lease_token=?",company,id,company,id,lease);}
    }
    private void stopReturn(String company,long id,Map<String,Object> op){Map<String,Object> report=data(returns.detail(company,id,SecurityConstants.INNER));Map<String,Object> doc=maps(report.get("documents")).stream().filter(d->number(d,"id")==number(op,"document_id")).findFirst().orElseThrow(()->new IllegalArgumentException("原退回单缺失"));
        boolean localUnsent="PENDING".equals(text(doc,"dispatch_state"))&&number(doc,"attempts")==0&&text(doc,"external_order").isEmpty()&&number(doc,"accepted_quantity")==0&&number(doc,"posted_quantity")==0;
        require(number(report,"pending_review_count")==0||localUnsent,"退回回传待人工核对，仓库截单保持待处理；仅从未下发且无实收的新安排可先本地撤回");if(number(doc,"accepted_quantity")==number(doc,"quantity"))return;
        if("REJECTED".equals(text(doc,"cancel_state"))){data(returns.document(company,id,number(doc,"id"),"query",Collections.emptyMap(),SecurityConstants.INNER));throw new IllegalArgumentException("仓库曾拒绝截单，已查询原单；请核对查询结果后再继续");}
        Map<String,Object> reply=data(returns.document(company,id,number(doc,"id"),"cancel",map("document_version",doc.get("control_version"),"mode",op.get("mode"),"reason",op.get("reason"),"actor",op.get("actor")),SecurityConstants.INNER));Map<String,Object> latest=maps(reply.get("documents")).stream().filter(d->number(d,"id")==number(doc,"id")).findFirst().orElseThrow(()->new IllegalArgumentException("截单回执缺少原单"));require("CONFIRMED".equals(text(latest,"cancel_state")),"退回仓库截单尚未确认，保留原安排；"+text(latest,"last_error"));cacheReturn(company,id,reply);
    }
    private void cacheReturn(String company,long id,Map<String,Object> reply){repository.db().update("UPDATE oms_exchange SET return_result=?,return_sn=? WHERE company_code=? AND id=?",encode(returnSnapshot(reply)),reply.get("return_sn"),company,id);}
    private Map<String,Object> shipment(String company,long id,long document,boolean locked){return repository.db().query("SELECT * FROM oms_order_shipment WHERE company_code=? AND exchange_id=? AND business_type='EXCHANGE' AND id=?"+(locked?" FOR UPDATE":""),ROW,company,id,document).stream().findFirst().orElseThrow(()->new IllegalArgumentException("原换出发货单不存在"));}
    private void guardReceipts(String company,Map<String,Object> sh){long document=number(sh,"id");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_outbound WHERE company_code=? AND shipment_id=? AND state<>'COMPLETED'",Long.class,company,document)==0,"换出存在待记账回执，截单不能释放库存");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=? AND state<>'COMPLETED'",Long.class,company,document)==0,"换出存在待确认虚拟出库");List<Map<String,Object>> reviews=data(wms.reviewSummaries(company,Collections.singletonList(document),SecurityConstants.INNER));require(reviews.stream().allMatch(r->number(r,"pending_count")==0),"换出回传待人工核对，截单不能释放库存");require(data(wms.receipts(company,text(sh,"shipment_sn"),true,SecurityConstants.INNER)).isEmpty(),"换出存在仓库回传待记账，请先核对");}
    private void stopOutbound(String company,long id,Map<String,Object> op){
        tx().execute(s->{Map<String,Object> e=exchanges.row(company,id,true);Map<String,Object> sh=shipment(company,id,number(op,"document_id"),true);List<Map<String,Object>> lines=repository.db().query("SELECT * FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=? ORDER BY id FOR UPDATE",ROW,company,sh.get("id"));long remaining=lines.stream().mapToLong(l->number(l,"quantity")-number(l,"shipped_quantity")-number(l,"cancelled_quantity")).sum();if(remaining==0)return null;
            guardReceipts(company,sh);List<Map<String,Object>> dispatch=repository.db().query("SELECT * FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=? FOR UPDATE",ROW,company,sh.get("id"));
            if(!dispatch.isEmpty()&&!"CANCELED".equals(text(dispatch.get(0),"state"))){Map<String,Object> frozen=object(dispatch.get(0).get("payload_json"));require(hash(text(dispatch.get(0),"payload_json")).equals(text(dispatch.get(0),"payload_hash")),"原换出下发快照校验失败");Map<String,Object> reply=data(wms.cancel(company,map("shipment_sn",sh.get("shipment_sn"),"payload",frozen,"reason",op.get("reason")),SecurityConstants.INNER));require(number(reply,"shipment_id")==number(sh,"id")&&text(reply,"shipment_sn").equals(text(sh,"shipment_sn"))&&text(reply,"payload_hash").equals(text(dispatch.get(0),"payload_hash")),"仓库截单回执身份不一致");require("CONFIRMED".equals(text(reply,"cancel_state")),"换出仓库截单尚未确认："+text(reply,"last_error"));guardReceipts(company,sh);repository.db().update("UPDATE oms_order_shipment_dispatch SET state='CANCELED',lease_token=NULL,lease_until=NULL WHERE company_code=? AND shipment_id=?",company,sh.get("id"));}
            Map<String,Object> current=repository.db().query("SELECT * FROM oms_exchange_control WHERE company_code=? AND id=? FOR UPDATE",ROW,company,op.get("id")).get(0);
            if(current.get("stock_request")==null){List<Map<String,Object>> allocations=new ArrayList<>();for(Map<String,Object> l:lines){long qty=number(l,"quantity")-number(l,"shipped_quantity")-number(l,"cancelled_quantity");if(qty>0)allocations.add(map("sku_sn",l.get("sku_sn"),"stock_source_id",l.get("stock_source_id"),"allocation_id",l.get("allocation_id"),"quantity",qty,"outbound_before",l.get("shipped_quantity")));}Map<String,Object> command=map("request_id","CFHH"+op.get("id"),"mode","WITHDRAW".equals(text(op,"mode"))?"REPLAN":"TERMINATE","channel_id",e.get("channel_id"),"platform_tid",stockReference(sh),"allocations",allocations);repository.db().update("UPDATE oms_exchange_control SET stock_request=? WHERE company_code=? AND id=?",encode(command),company,op.get("id"));}return null;});
        // Warehouse acknowledgement and immutable stock request survive a stock RPC timeout independently.
        tx().execute(s->{Map<String,Object> e=exchanges.row(company,id,true);Map<String,Object> sh=shipment(company,id,number(op,"document_id"),true);Map<String,Object> current=repository.db().query("SELECT * FROM oms_exchange_control WHERE company_code=? AND id=? FOR UPDATE",ROW,company,op.get("id")).get(0);if(current.get("stock_request")==null)return null;guardReceipts(company,sh);Map<String,Object> command=object(current.get("stock_request")),reply=data(inventory.adjust(company,command,SecurityConstants.INNER));verifyStock(command,reply);syncStock(company,id,e,reply);
            repository.db().update("UPDATE oms_order_shipment_line SET cancelled_quantity=quantity-shipped_quantity WHERE company_code=? AND shipment_id=?",company,sh.get("id"));long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",Long.class,company,sh.get("id"));repository.db().update("UPDATE oms_order_shipment SET cancelled_quantity=quantity-?,status=?,cancelled_at=NOW(),control_version=control_version+1 WHERE company_code=? AND id=?",shipped,shipped==0?"VOIDED":"PART_SHIPPED",company,sh.get("id"));repository.db().update("INSERT INTO oms_order_shipment_log(company_code,shipment_id,action,result,message,operator_name) VALUES (?,?,'CUTOFF_COMPLETE','SUCCESS',?,?)",company,sh.get("id"),"换货截单#"+op.get("id")+"：剩余停止，已出库保留；"+("WITHDRAW".equals(text(op,"mode"))?"逻辑预占保留":"未发占用已释放"),op.get("actor"));repository.shipmentChanged(company,number(sh,"id"));return null;});
        refreshAllocation(company,id);
    }
    private void verifyStock(Map<String,Object> command,Map<String,Object> reply){require("COMPLETED".equals(text(reply,"state"))&&text(command,"request_id").equals(text(reply,"request_id"))&&text(command,"mode").equals(text(reply,"mode")),"原截单库存回执尚未确认");}
    private void syncStock(String company,long id,Map<String,Object> e,Map<String,Object> reply){List<Map<String,Object>> lines=maps(reply.get("lines"));require(lines.size()==1&&text(lines.get(0),"sku_sn").equals(text(e,"target_sku"))&&text(lines.get(0),"platform_oid").equals(text(e,"platform_oid")),"库存回执与换出需求不一致");Map<String,Object> line=lines.get(0);if(e.get("fulfillment_line_id")!=null)require(repository.db().update("UPDATE oms_order_line SET reserved_quantity=?,cancelled_quantity=? WHERE company_code=? AND id=? AND exchange_id=? AND business_type='EXCHANGE'",line.get("reserved_quantity"),line.get("cancelled_quantity"),company,e.get("fulfillment_line_id"),id)==1,"换出明细关联不一致");repository.db().update("UPDATE oms_exchange SET stock_receipt=? WHERE company_code=? AND id=?",encode(line),company,id);}
    private void refreshAllocation(String company,long id){Map<String,Object> e=exchanges.row(company,id,false);if(e.get("stock_request")==null)return;List<Map<String,Object>> receipts=data(inventory.receipts(company,number(e,"channel_id"),ExchangeRounds.reference(e),SecurityConstants.INNER));long allocated=receipts.stream().mapToLong(r->number(r,"quantity")).sum();repository.db().update("UPDATE oms_exchange SET allocation_quantity=?,allocation_receipts=?,allocation_status=? WHERE company_code=? AND id=?",allocated,encode(receipts),allocated==ExchangeRounds.quantityOf(e)?"FULL":allocated>0?"PART":"NONE",company,id);}
    private void finishCancel(String company,long id,Map<String,Object> op){
        require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_control WHERE company_code=? AND parent_id=? AND state<>'COMPLETED'",Long.class,company,op.get("id"))==0,"退回或换出截单尚未全部确认");Map<String,Object> e=exchanges.row(company,id,false);Map<String,Object> returned=text(e,"return_sn").isEmpty()?Collections.emptyMap():data(returns.detail(company,id,SecurityConstants.INNER));require(number(returned,"pending_review_count")==0&&number(returned,"accepted_quantity")==number(returned,"posted_quantity"),"退回仍有待核对或待入账事实");
        for(Map<String,Object> sh:repository.db().query("SELECT * FROM oms_order_shipment WHERE company_code=? AND exchange_id=? AND business_type='EXCHANGE'",ROW,company,id))guardReceipts(company,sh);
        if(e.get("stock_request")!=null){Map<String,Object> command=map("request_id","CFHH"+op.get("id")+"FINAL","mode","TERMINATE","channel_id",e.get("channel_id"),"platform_tid",ExchangeRounds.reference(e),"allocations",Collections.emptyList(),"finish_order",true);Map<String,Object> reply=data(inventory.adjust(company,command,SecurityConstants.INNER));verifyStock(command,reply);syncStock(company,id,e,reply);refreshAllocation(company,id);}
        long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(l.shipped_quantity),0) FROM oms_order_shipment_line l JOIN oms_order_shipment sh ON sh.company_code=l.company_code AND sh.id=l.shipment_id WHERE sh.company_code=? AND sh.exchange_id=? AND sh.business_type='EXCHANGE'",Long.class,company,id);boolean facts=number(returned,"accepted_quantity")>0||shipped>0;
        if(!returned.isEmpty())cacheReturn(company,id,returned);
        tx().execute(s->{Map<String,Object> locked=exchanges.row(company,id,true);repository.db().update("UPDATE oms_exchange SET state=?,control_state=?,stage=IF(?,'FINISHED',stage),control_version=control_version+1 WHERE company_code=? AND id=?",facts?"BLOCKED":"CANCELED",facts?"CANCEL_REVIEW":"CANCELED",!facts,company,id);repository.db().update("UPDATE oms_exchange_control SET state=?,last_error=? WHERE company_code=? AND id=?",facts?"REVIEW":"COMPLETED",facts?"剩余已停止，存在实收入账或实际换出，请确认后续处理并保留事实":"",company,op.get("id"));exchanges.event(company,id,"CANCEL_RESULT",facts?"BLOCKED":"CANCELED",number(locked,"control_version")+1,facts?"剩余履约已截停；已有实收或实发，待人工确认结束方案":"出入库截单及未发库存释放已确认；OMS换货已取消，平台申请状态需另行核对",map("accepted_quantity",number(returned,"accepted_quantity"),"shipped_quantity",shipped),text(op,"actor"));return null;});
    }
    public Map<String,Object> close(String company,long id,Map<String,Object> input,String actor){Map<String,Object> before=exchanges.row(company,id,false);Map<String,Object> report=text(before,"return_sn").isEmpty()?Collections.emptyMap():data(returns.detail(company,id,SecurityConstants.INNER));tx().execute(s->{Map<String,Object> e=editable(company,id,input);require("CANCEL_REVIEW".equals(text(e,"control_state")),"仅取消后存在执行事实的换货可确认结束");require(number(report,"pending_review_count")==0&&number(report,"accepted_quantity")==number(report,"posted_quantity"),"退回事实尚未核对完成");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_control WHERE company_code=? AND exchange_id=? AND kind<>'CANCEL' AND state<>'COMPLETED'",Long.class,company,id)==0,"仍有截单未完成");String reason=text(input,"reason").trim(),evidence=text(input,"evidence").trim();require(!reason.isEmpty()&&reason.length()<=500&&!evidence.isEmpty()&&evidence.length()<=500,"请填写后续处理结论和凭证");repository.db().update("UPDATE oms_exchange SET state='CLOSED',stage='FINISHED',control_state='CLOSED',next_attempt=NULL,control_version=control_version+1 WHERE company_code=? AND id=?",company,id);repository.db().update("UPDATE oms_exchange_control SET state='COMPLETED',evidence=?,last_error='' WHERE company_code=? AND exchange_id=? AND kind='CANCEL' AND state='REVIEW'",encode(map("reason",reason,"evidence",evidence,"actor",actor)),company,id);exchanges.event(company,id,"CANCEL_CLOSE","CLOSED",number(e,"control_version")+1,"取消后人工结束："+reason+"；实收实发与来源额度保留，未撤销库存事实",map("evidence",evidence),actor);return null;});return exchanges.detail(company,id);}
    private void complete(String company,Map<String,Object> op){tx().execute(s->{Map<String,Object> e=exchanges.row(company,number(op,"exchange_id"),true);repository.db().update("UPDATE oms_exchange_control SET state='COMPLETED',last_error='' WHERE company_code=? AND id=?",company,op.get("id"));repository.db().update("UPDATE oms_exchange SET control_version=control_version+1 WHERE company_code=? AND id=?",company,op.get("exchange_id"));exchanges.event(company,number(op,"exchange_id"),"CUTOFF_RESULT",text(e,"state"),number(e,"control_version")+1,("RETURN".equals(text(op,"kind"))?"退回":"换出")+"截单核对完成；已执行事实保留",map("operation_id",op.get("id"),"document_id",op.get("document_id")),text(op,"actor"));return null;});}
    private void blocked(String company,Map<String,Object> op,RuntimeException failure){String message=failure instanceof IllegalArgumentException?failure.getMessage():"跨服务结果尚未确认，请核对原请求；占用保留";if(message==null)message="截单待核对";message=message.substring(0,Math.min(500,message.length()));repository.db().update("UPDATE oms_exchange_control SET state='REVIEW',last_error=? WHERE company_code=? AND id=?",message,company,op.get("id"));}
}
